export const sha256=(v:string|Buffer)=>crypto.createHash('sha256').update(v).digest('hex');
export const canonical=(v:unknown):string=>JSON.stringify(sortDeep(v));
function sortDeep(v:unknown):unknown{if(Array.isArray(v))return v.map(sortDeep);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>[k,sortDeep(x)]));return v;}
export const jsonBytes=(v:unknown)=>Buffer.from(`${canonical(v)}\n`);
export function writeJson(file:string,value:unknown){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,jsonBytes(value));}
export function readJson(file:string){return JSON.parse(fs.readFileSync(file,'utf8'));}

