export async function acquire(output=CAPTURE_INPUT,fetchImpl:typeof fetch=fetch){const authoring=readJson(AUTHORING_INPUT);if(sha256(fs.readFileSync(AUTHORING_INPUT))!==EXPECTED_AUTHORING_SHA256)throw new Error('canonical authoring input seal mismatch');const responseCache=new Map<string,Promise<Response>>(),cachedFetch=(async(input:any,init:any)=>{const key=String(input);let pending=responseCache.get(key);if(!pending){pending=fetchImpl(input,init);responseCache.set(key,pending);}return(await pending).clone();})as typeof fetch;const receipts:Receipt[]=[];for(const source of authoring.sources)receipts.push(await captureReceipt(source,cachedFetch));assertReceiptSemantics(authoring.sources,receipts);const value={schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,authoring_sha256:EXPECTED_AUTHORING_SHA256,capture_policy:'exact_allowlisted_public_get_no_redirect_follow',receipts};validateCaptureInputSchema(value);writeJson(output,value);return receipts;}

