 const familyIds=authoring.families.map((f:any)=>f.family_id);if(new Set(familyIds).size!==familyIds.length)throw new Error('duplicate family id');const sourceIds=new Set(authoring.sources.map((s:any)=>s.source_id));for(const s of authoring.sources){if(!familyIds.includes(s.family_id))throw new Error('source family is undeclared');if(s.source_id===s.family_id)throw new Error('source/family self dependency');}for(const e of objects['source-graph'].edges){if(!sourceIds.has(e.source_id)||!familyIds.includes(e.depends_on_family_id)||e.source_id===e.depends_on_family_id)throw new Error('dangling or self dependency edge');const s=authoring.sources.find((x:any)=>x.source_id===e.source_id);if(s.independence!=='family_limited'||s.family_id!==e.depends_on_family_id)throw new Error('source family independence inconsistency');}const expectedEdges=authoring.sources.filter((s:any)=>s.independence==='family_limited').map((s:any)=>({source_id:s.source_id,depends_on_family_id:s.family_id}));exact(objects['source-graph'],{schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,families:authoring.families,edges:expectedEdges},'source graph');
 for(const s of authoring.sources)if(s.expected_content.policy==='markers_required'&&(s.provenance.mode!=='online_marker_required'||s.expected_content.marker_concepts.length<3))throw new Error('marker-required source lacks specific multi-concept gate');assertReceiptSemantics(authoring.sources,captureInput.receipts);assertDuplicateIndependence(authoring.sources,captureInput.receipts);
 const receiptById=new Map(captureInput.receipts.map((r:any)=>[r.source_id,r]));const expectedCapture={schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,sources:authoring.sources.map((s:any)=>({...s,retrieval:receiptById.get(s.source_id),evidence:{status:evidenceStatus(s,receiptById.get(s.source_id) as Receipt),promotion_eligible:false,limitation:s.provenance.mode==='manual_bounded_transcription'?'Manual transcription remains pending separate review.':s.provenance.mode==='predecessor_metadata'?'Same-family predecessor metadata remains pending separate review.':(receiptById.get(s.source_id) as any).outcome==='captured_marker_matched'?'Content identity markers matched, but claim review is still pending.':'Transport did not establish proposition evidence.'}}))};exact(objects['capture-ledger'],expectedCapture,'capture ledger');exact(objects['record-ledgers'],{schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,records:authoring.records},'record ledgers');
 for(const claim of objects['pending-claims'].claims)for(const id of [...claim.supporting_source_ids,...claim.contradicting_source_ids]){const source=expectedCapture.sources.find((s:any)=>s.source_id===id);if(!source||source.evidence.status==='not_evidence')throw new Error(`not_evidence source cannot support or contradict a claim: ${id}`);}
 const expectedClaims={schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,claims:authoring.claims.map((c:any)=>({...c,status:'pending_claim_review',evidence_boundary:'Only exact authored locators and bound source observations; transport availability alone is not proposition evidence.',support_assessment:[...c.supporting_source_ids,...c.contradicting_source_ids].map((id:string)=>{const s=expectedCapture.sources.find((x:any)=>x.source_id===id);return{source_id:id,evidence_status:s.evidence.status,promotion_eligible:false};}),separate_review_required:true,promotion_eligibility:'ineligible_pending_separate_review',promotion_target:null}))};exact(objects['pending-claims'],expectedClaims,'pending claims');exact(objects['unresolved-leads'],{schema_version:SCHEMA_VERSION,artifact_id:ARTIFACT_ID,items:authoring.unresolved.map((x:any)=>({...x,status:'unresolved'}))},'unresolved mappings');
 for(const claim of objects['pending-claims'].claims){if(claim.status!=='pending_claim_review'||claim.promotion_target!==null||claim.promotion_eligibility!=='ineligible_pending_separate_review')throw new Error('promoted claim/status tamper');for(const assessment of claim.support_assessment)if(assessment.promotion_eligible!==false)throw new Error('unsupported source made promotion eligible');}
