 function scanStrings(value:any,key=''){if(typeof value==='string'){if(key!=='query_names'&&hasSensitiveToken(value))throw new Error('secret-bearing string value rejected');return;}if(Array.isArray(value)){for(const item of value)scanStrings(item,key);return;}if(value&&typeof value==='object')for(const[k,v]of Object.entries(value)){if(hasSensitiveToken(k))throw new Error('secret-bearing member key rejected');scanStrings(v,k);}}for(const file of allowed)scanStrings(JSON.parse(fs.readFileSync(path.join(root,file),'utf8')));return{descriptor_sha256:dh,authoring_sha256:EXPECTED_AUTHORING_SHA256,capture_sha256:EXPECTED_CAPTURE_SHA256,research_records:6,promoted_claims:0,verified_dossiers:0,benchmark_tasks:0,search_tasks:0,pending_claims:authoring.claims.length,unresolved_items:authoring.unresolved.length};
